<?php
namespace App\Models;
use App\Enums\ReplacementStatus;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['replacement_code','assignment_id','customer_id','customer_requirement_id','old_worker_id','reason','reason_details','requested_date','replacement_required_date','status','requested_by','approved_by','approved_at','new_worker_id','replacement_assignment_id','completed_at','remarks'])]
class ReplacementRequest extends Model { protected static function booted():void{static::updating(fn(self $m)=>$m->isDirty('replacement_code')?$m->replacement_code=$m->getOriginal('replacement_code'):null);} public function assignment():BelongsTo{return $this->belongsTo(Assignment::class);}public function customer():BelongsTo{return $this->belongsTo(Customer::class);}public function requirement():BelongsTo{return $this->belongsTo(CustomerRequirement::class,'customer_requirement_id');}public function oldWorker():BelongsTo{return $this->belongsTo(Worker::class,'old_worker_id');}public function newWorker():BelongsTo{return $this->belongsTo(Worker::class,'new_worker_id');}public function replacementAssignment():BelongsTo{return $this->belongsTo(Assignment::class,'replacement_assignment_id');}public function statusHistory():HasMany{return $this->hasMany(ReplacementStatusHistory::class);}protected function casts():array{return ['requested_date'=>'date','replacement_required_date'=>'date','approved_at'=>'datetime','completed_at'=>'datetime','status'=>ReplacementStatus::class];} }
